create table if not exists public.record_relief_uploads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'uploaded' check(status in('uploaded','processing','needs_review','confirmed','failed','deleted')),mime_type text not null,byte_size bigint not null check(byte_size between 1 and 15728640),storage_path text not null,extraction jsonb,model_version text,extracted_at timestamptz,failure_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.record_relief_uploads enable row level security;create policy "members read own relief uploads" on public.record_relief_uploads for select using(auth.uid()=user_id);create policy "members create own relief uploads" on public.record_relief_uploads for insert with check(auth.uid()=user_id);create policy "members update own relief uploads" on public.record_relief_uploads for update using(auth.uid()=user_id) with check(auth.uid()=user_id);insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('record-relief-uploads','record-relief-uploads',false,15728640,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;create policy "members upload own relief files" on storage.objects for insert to authenticated with check(bucket_id='record-relief-uploads' and (storage.foldername(name))[1]=auth.uid()::text);create policy "members read own relief files" on storage.objects for select to authenticated using(bucket_id='record-relief-uploads' and (storage.foldername(name))[1]=auth.uid()::text);create policy "members delete own relief files" on storage.objects for delete to authenticated using(bucket_id='record-relief-uploads' and (storage.foldername(name))[1]=auth.uid()::text);